import sys

def count_grey_squares(R, C, K):
    def is_white(r, c):
        return bin(r | c).count('1') > 0

    total_grey = 0
    r, c = 0, 0
    dr, dc = 0, 1

    for _ in range(K):
        if is_white(r, c):
            total_grey += 1

        r += dr
        c += dc

        if r < 0 or r >= R or c < 0 or c >= C:
            dr, dc = -dr, -dc
            r += 2 * dr
            c += 2 * dc
            if r < 0:
                r, dr = 0, 1
            elif r >= R:
                r, dr = R - 1, -1
            if c < 0:
                c, dc = 0, 1
            elif c >= C:
                c, dc = C - 1, -1

    return total_grey

